"""Intent tests for risk.log_returns (M1-T16; RISK-01, TC-04)."""

from __future__ import annotations

import math

import pytest
from mdata import Prices
from risk import Returns, log_returns


def _prices(payload: dict) -> Prices:
    return Prices(
        dates=tuple(payload["dates"]),
        tickers=tuple(payload["tickers"]),
        closes={t: tuple(c) for t, c in payload["closes"].items()},
    )


@pytest.mark.intent
def test_tc04_geometric_closes_match_closed_form(golden) -> None:
    given, expected = golden("risk", "TC-04")
    returns = log_returns(_prices(given["prices"]))
    assert isinstance(returns, Returns)
    assert returns.tickers == tuple(expected["tickers"])
    for ticker in expected["tickers"]:
        assert len(returns.values[ticker]) == len(expected["values"][ticker])
        assert list(returns.values[ticker]) == pytest.approx(
            expected["values"][ticker], abs=expected["tol"], rel=0
        )


@pytest.mark.intent
def test_tc04_dates_are_prices_dates_after_the_base(golden) -> None:
    given, expected = golden("risk", "TC-04")
    returns = log_returns(_prices(given["prices"]))
    assert returns.base_date == expected["base_date"]
    assert returns.dates == tuple(expected["dates"])


@pytest.mark.intent
def test_risk01_return_is_log_ratio_dated_t(contract_sample) -> None:
    payload = contract_sample("mdata.Prices")
    returns = log_returns(_prices(payload))
    assert returns.base_date == payload["dates"][0]
    assert returns.dates == tuple(payload["dates"][1:])
    for ticker in payload["tickers"]:
        closes = payload["closes"][ticker]
        want = [math.log(closes[i] / closes[i - 1]) for i in range(1, len(closes))]
        assert list(returns.values[ticker]) == pytest.approx(want, abs=1e-12, rel=0)


@pytest.mark.intent
def test_fewer_than_two_dates_raises(contract_sample) -> None:
    payload = contract_sample("mdata.Prices")
    one_date = {
        "dates": payload["dates"][:1],
        "tickers": payload["tickers"],
        "closes": {t: c[:1] for t, c in payload["closes"].items()},
    }
    with pytest.raises(ValueError, match=r"(?i)two|date"):
        log_returns(_prices(one_date))

